package main

import (
	"encoding/json"
	"fmt"
	"os"
)

type exportReport struct {
	ManifestName  string       `json:"manifest_name"`
	OverallStatus string       `json:"overall_status"`
	Steps         []exportStep `json:"steps"`
}

type exportStep struct {
	ID      string            `json:"id"`
	Status  string            `json:"status"`
	Outputs []json.RawMessage `json:"outputs"`
}

func exportCmd(args []string) {
	if len(args) != 1 {
		fmt.Fprintln(os.Stderr, "usage: repro-verify export <report.json>")
		os.Exit(2)
	}

	path := args[0]
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			fmt.Fprintf(os.Stderr, "error: export file not found: %s\n", path)
		} else {
			fmt.Fprintf(os.Stderr, "error: invalid export input: %s: %s\n", path, err)
		}
		os.Exit(2)
	}

	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid export input: %s: %s\n", path, err)
		os.Exit(2)
	}

	for _, field := range []string{"manifest_name", "overall_status", "steps"} {
		if _, ok := raw[field]; !ok {
			fmt.Fprintf(os.Stderr, "error: invalid export input: %s: missing required field %s\n", path, field)
			os.Exit(2)
		}
		if string(raw[field]) == "null" {
			fmt.Fprintf(os.Stderr, "error: invalid export input: %s: %s must not be null\n", path, field)
			os.Exit(2)
		}
	}

	var rep exportReport
	if err := json.Unmarshal(data, &rep); err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid export input: %s: %s\n", path, err)
		os.Exit(2)
	}

	var rawSteps []map[string]json.RawMessage
	if err := json.Unmarshal(raw["steps"], &rawSteps); err != nil {
		fmt.Fprintf(os.Stderr, "error: invalid export input: %s: %s\n", path, err)
		os.Exit(2)
	}
	for i, step := range rawSteps {
		if _, ok := step["id"]; !ok || string(step["id"]) == "null" {
			fmt.Fprintf(os.Stderr, "error: invalid export input: %s: step %d missing required field id\n", path, i)
			os.Exit(2)
		}
		if _, ok := step["status"]; !ok || string(step["status"]) == "null" {
			fmt.Fprintf(os.Stderr, "error: invalid export input: %s: step %d missing required field status\n", path, i)
			os.Exit(2)
		}
	}

	fmt.Println("step_id,status,output_count")
	for _, step := range rep.Steps {
		fmt.Printf("%s,%s,%d\n", step.ID, step.Status, len(step.Outputs))
	}
}
EOF
